-- Deutsch: Validiert die von `l3build check` hinterlassenen Test-PDFs eines
-- Moduls mit veraPDF und vergleicht die verletzten Regeln mit der Baseline
-- des Moduls (<modul>/verapdf-baseline.lua). Jede nicht verzeichnete
-- Verletzung ist ein Fehler; verzeichnete Regeln, die nicht mehr verletzt
-- werden, erscheinen als Warnung.
-- English: Validates the test PDFs left behind by `l3build check` for a module
-- with veraPDF and compares the violated rules with the module's baseline
-- (<module>/verapdf-baseline.lua). Every violation not listed is an error;
-- listed rules that are no longer violated are reported as a warning.
--
-- Aufruf / usage, from the repository root:
--   texlua .github/scripts/check-verapdf.lua [--require] <module>
--   texlua .github/scripts/check-verapdf.lua --update <module> [pdf ...]
--
-- Die Baseline ordnet jedem PDF (Pfad relativ zu build/) die Regelklauseln zu,
-- die es verletzen darf. Ohne --require wird ohne veraPDF übersprungen.
-- The baseline maps each PDF (path relative to build/) to the rule clauses it
-- may violate. Without --require the check is skipped when veraPDF is missing.

local builddir = "build"

local function shell_quote(value)
  return "'" .. tostring(value):gsub("'", "'\\''") .. "'"
end

-- Deutsch: Lua 5.1 liefert einen Statuscode, neuere Versionen true/nil.
-- English: Lua 5.1 returns a status code; newer versions return true/nil.
local function succeeded(status)
  return status == true or status == 0
end

local function command_exists(name)
  return succeeded(os.execute("command -v " .. shell_quote(name) .. " >/dev/null 2>&1"))
end

local require_tool, update = false, false
local positional = {}
for _, value in ipairs(arg) do
  if value == "--require" then
    require_tool = true
  elseif value == "--update" then
    update = true
  else
    positional[#positional + 1] = value
  end
end

local module = positional[1]
if not module then
  io.stderr:write("usage: check-verapdf.lua [--require|--update] <module> [pdf ...]\n")
  os.exit(2)
end
local baseline_file = module .. "/verapdf-baseline.lua"

if not command_exists("verapdf") then
  if require_tool then
    print("verapdf: veraPDF is required but not on PATH")
    os.exit(1)
  end
  print("verapdf: SKIP " .. module .. " (veraPDF not installed or not on PATH)")
  os.exit(0)
end

local baseline = {}
do
  local chunk = loadfile(baseline_file)
  if chunk then
    baseline = chunk()
  elseif not update then
    print("verapdf: " .. baseline_file .. " not found")
    os.exit(1)
  end
end

local pdfs = {}
if update and #positional > 1 then
  for index = 2, #positional do
    pdfs[#pdfs + 1] = positional[index]
  end
else
  for pdf in pairs(baseline) do
    if pdf ~= "flavour" then
      pdfs[#pdfs + 1] = pdf
    end
  end
end
table.sort(pdfs)
assert(#pdfs > 0, "no PDFs to validate for " .. module)

local flavour = baseline.flavour or "ua2"
local arguments = { "verapdf", "--flavour", flavour, "--format", "xml" }
for _, pdf in ipairs(pdfs) do
  arguments[#arguments + 1] = builddir .. "/" .. pdf
end
local quoted = {}
for index, value in ipairs(arguments) do
  quoted[index] = shell_quote(value)
end

-- Deutsch: veraPDF endet mit Exit-Code 1, sobald ein PDF nicht konform ist;
-- maßgeblich ist allein der Bericht.
-- English: veraPDF exits with code 1 whenever a PDF is non-conforming; only
-- the report matters here.
local report = os.tmpname()
os.execute(table.concat(quoted, " ") .. " > " .. shell_quote(report) .. " 2>/dev/null")
local handle = assert(io.open(report, "r"))
local xml = handle:read("*a")
handle:close()
os.remove(report)

local violated = {}
for job in xml:gmatch("<job>(.-)</job>") do
  local name = job:match("<name>(.-)</name>")
  local clauses = {}
  for attributes in job:gmatch("<rule ([^>]-)>") do
    if attributes:find('status="failed"', 1, true) then
      clauses[attributes:match('clause="([^"]*)"')] = true
    end
  end
  local parsed = job:find("<validationReport", 1, true) ~= nil
  violated[name] = parsed and clauses or false
end

-- Deutsch: veraPDF meldet absolute Pfade.
-- English: veraPDF reports absolute paths.
local function result_for(pdf)
  local suffix = "/" .. builddir .. "/" .. pdf
  for name, clauses in pairs(violated) do
    if name:sub(-#suffix) == suffix then
      return clauses
    end
  end
end

local function sorted_keys(set)
  local keys = {}
  for key in pairs(set) do
    keys[#keys + 1] = key
  end
  table.sort(keys)
  return keys
end

if update then
  local lines = {
    "-- Deutsch: Von veraPDF verletzte Regeln je Test-PDF;",
    "-- English: Rules violated per test PDF as reported by veraPDF;",
    "-- erzeugt von / generated by .github/scripts/check-verapdf.lua --update",
    "return {",
    string.format("  flavour = %q,", flavour),
  }
  for _, pdf in ipairs(pdfs) do
    local clauses = result_for(pdf)
    assert(clauses, "veraPDF could not validate " .. pdf)
    local entries = {}
    for _, clause in ipairs(sorted_keys(clauses)) do
      entries[#entries + 1] = string.format("%q", clause)
    end
    lines[#lines + 1] = string.format("  [%q] = { %s },", pdf, table.concat(entries, ", "))
  end
  lines[#lines + 1] = "}"
  local out = assert(io.open(baseline_file, "w"))
  out:write(table.concat(lines, "\n"), "\n")
  out:close()
  print("verapdf: wrote " .. baseline_file)
  os.exit(0)
end

local failed = false
for _, pdf in ipairs(pdfs) do
  local clauses = result_for(pdf)
  if clauses == nil then
    print("verapdf: no result for " .. pdf .. " (missing from build/?)")
    failed = true
  elseif clauses == false then
    print("verapdf: could not validate " .. pdf)
    failed = true
  else
    local allowed = {}
    for _, clause in ipairs(baseline[pdf]) do
      allowed[clause] = true
    end
    local unexpected, stale = {}, {}
    for clause in pairs(clauses) do
      if not allowed[clause] then
        unexpected[#unexpected + 1] = clause
      end
    end
    for clause in pairs(allowed) do
      if not clauses[clause] then
        stale[#stale + 1] = clause
      end
    end
    table.sort(unexpected)
    table.sort(stale)
    if #unexpected > 0 then
      print("verapdf: ::error::" .. pdf .. " violates rules not in the baseline: "
        .. table.concat(unexpected, ", "))
      failed = true
    end
    if #stale > 0 then
      print("verapdf: ::warning::" .. pdf .. " no longer violates baseline rules: "
        .. table.concat(stale, ", "))
    end
  end
end

if failed then
  os.exit(1)
end
print("verapdf: " .. module .. ": " .. #pdfs .. " PDF(s) match the baseline")
